async def act(page):
    """
    - Attempt to use create_curated_collection_by_search if a complementary region is present.
    - Otherwise fall back to a relative navigation to '/?s=Tracing' (or '/?search=Tracing').
    - Wait for role='main', then click the second result (article -> link or heading -> link/heading).
    - If the helper ran, return its raw result unmodified; otherwise return an empty list.
    """

    # Detect whether a complementary region is present (the helper requires this)
    try:
        comp = page.get_by_role("complementary")
        comp_count = await comp.count()
    except Exception:
        comp_count = 0

    used_helper = False
    helper_results = None

    if comp_count > 0:
        # Try to use the site-aware helper (it will navigate to '/' and run the visible search)
        try:
            helper_results = await create_curated_collection_by_search(page, "Tracing", max_results=0, resolve_links=True)
            used_helper = True
        except Exception:
            # Helper failed; fall through to fallback navigation below
            used_helper = False
            helper_results = None

    if not used_helper:
        # Fallback: navigate to a common search URL relative to the current site
        try:
            await page.goto("/?s=Tracing")
        except Exception:
            try:
                await page.goto("/?search=Tracing")
            except Exception:
                # If navigation fails, give up
                return []

    # Wait for the results container (role="main") to be present; use networkidle fallback
    main = page.get_by_role("main")
    try:
        await main.wait_for(timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            pass

    async def _click_second_result_in_main():
        # Prefer article-based results
        articles = main.get_by_role("article")
        try:
            article_count = await articles.count()
        except Exception:
            article_count = 0

        if article_count >= 2:
            second_article = articles.nth(1)
            links = second_article.get_by_role("link")
            try:
                link_count = await links.count()
            except Exception:
                link_count = 0
            if link_count > 0:
                # Click the first link inside the second article (final action)
                await links.nth(0).click()
                return True
            return False

        # Fallback: headings-based results
        headings = main.get_by_role("heading")
        try:
            heading_count = await headings.count()
        except Exception:
            heading_count = 0

        if heading_count >= 2:
            second_heading = headings.nth(1)
            links = second_heading.get_by_role("link")
            try:
                link_count = await links.count()
            except Exception:
                link_count = 0
            if link_count > 0:
                await links.nth(0).click()
                return True
            # Try clicking the heading itself as a last resort
            try:
                await second_heading.click()
                return True
            except Exception:
                return False

        return False

    # Perform the click (best-effort). Make this the last UI action.
    try:
        await _click_second_result_in_main()
    except Exception:
        pass

    # If the helper ran, return its raw results unmodified (per API-return rule); otherwise return an empty list
    if used_helper:
        return helper_results
    return []

